[DataContractAttribute]
class HSMobileOpsExportStartResponse
{
    boolean success;
    str     errorCode;
    str     executionId;


}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

/// <summary>
/// Handed back to getExportStatus to poll this run - see HSMobileOpsCountingService's own
/// class doc: getExportStatus does not exist yet, so this id has nowhere to go yet either.
/// </summary>
[DataMemberAttribute('ExecutionId')]
public str parmExecutionId(str _value = executionId)
{
    executionId = _value;
    return executionId;
}
